BEGIN TRANSACTION;
CREATE TABLE app_settings (
	id INTEGER NOT NULL, 
	email_escritorio VARCHAR(255), antecedencia_mensal_dias INTEGER NOT NULL DEFAULT 7, antecedencia_anual_dias INTEGER NOT NULL DEFAULT 30, antecedencia_encerramento_dias INTEGER NOT NULL DEFAULT 180, email_assunto TEXT, email_corpo TEXT, frequencia_mensal_dias INTEGER DEFAULT 3, frequencia_anual_dias INTEGER DEFAULT 7, frequencia_encerramento_dias INTEGER DEFAULT 30, 
	PRIMARY KEY (id)
);

Segue um lembrete automático de obrigação contratual.

Recorrência: {tipo}
Documento: {documento}
Item: {item}
Obrigação: {obrigacao}
Próximo lembrete: {prazo}
Status atual: {status}{tipo}',3,7,30);
CREATE TABLE contracts (
	id INTEGER NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	code VARCHAR(100), 
	description TEXT, 
	is_active BOOLEAN NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, signed_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE obligation_dependencies (
	id INTEGER NOT NULL, 
	eventual_id INTEGER NOT NULL, 
	condition_id INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_dep_pair UNIQUE (eventual_id, condition_id), 
	FOREIGN KEY(eventual_id) REFERENCES obligations (id), 
	FOREIGN KEY(condition_id) REFERENCES obligations (id)
);
CREATE TABLE obligation_status_history (
	id INTEGER NOT NULL, 
	obligation_id INTEGER NOT NULL, 
	old_status VARCHAR(50), 
	new_status VARCHAR(50) NOT NULL, 
	note TEXT, 
	changed_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(obligation_id) REFERENCES obligations (id)
);
CREATE TABLE obligations (
	id INTEGER NOT NULL, 
	contract_id INTEGER NOT NULL, 
	document_name VARCHAR(255), 
	item_number VARCHAR(100), 
	recurrence VARCHAR(100), 
	obligation_text TEXT NOT NULL, 
	observations TEXT, 
	status VARCHAR(50) NOT NULL, 
	responsible VARCHAR(255), 
	deadline DATETIME, 
	source_row INTEGER, 
	email_enabled BOOLEAN NOT NULL, 
	email_destino VARCHAR(255), 
	manual_reminder_at DATETIME, 
	manual_reminder_sent_at DATETIME, 
	recurrence_mode VARCHAR(20), 
	recurrence_time VARCHAR(5), 
	recurrence_interval_days INTEGER, 
	recurrence_weekday INTEGER, 
	recurrence_day_of_month INTEGER, 
	recurrence_month INTEGER, 
	next_recurrence_at DATETIME, 
	next_reminder_at DATETIME, 
	last_email_sent_at DATETIME, 
	status_envio VARCHAR(50), 
	trigger_family VARCHAR(50), 
	trigger_type VARCHAR(100), 
	condition_raw TEXT, 
	condition_canonical VARCHAR(255), 
	condition_status VARCHAR(50), 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL, obligation_code VARCHAR(20), contract_phase TEXT, trigger_category TEXT, compliance_logic VARCHAR(50), trigger_source TEXT, internal_inputs TEXT, external_inputs TEXT, depends_on_clauses TEXT, is_input_for_clauses TEXT, deadline_type VARCHAR(50), deadline_value TEXT, deadline_text TEXT, expected_output TEXT, interpretive_notes TEXT, pagina_contrato INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(contract_id) REFERENCES contracts (id)
);

