INSERT INTO "obligations" VALUES(1,1,'Contrato','5.3 (ii) e 35.1','Periódica - Mensal','Pagar a OUTORGA VARIÁVEL ao Poder Concedente (1% da receita bruta auferida) a partir do 13º mês da concessão e o ÔNUS DE FISCALIZAÇÃO à ARTESP (0,5% da receita bruta), conforme periodicidade definida no Anexo 06 e nas Cláusulas contratuais.',NULL,'pending','Concessionária',NULL,2,1,'sofiaishizaki.2@gmail.com',NULL,NULL,'monthly','08:00',NULL,NULL,NULL,NULL,'2026-07-01 00:00:00.000000','2026-06-24 00:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0001','Todas as fases','Calendário (cron mensal)','no_ciclo','Fechamento de mês (Adicionado por IA: cadência mensal explicitada pela Recorrência)','Registros contábeis da SPE; Saldo da Conta Centralizadora; Receita auferida no período (tarifária e/ou não-tarifária); Comprovantes de regularidade fiscal e tributária','Tribunais e instâncias judiciais (quando aplicável)','cl. 16.1 (vii) escrituração contábil; cl. 33.6 conta centralizadora','cl. 5.3 (ii) e 35.1 (cálculo da outorga variável)','recorrente','{frequência: mensal; data_referência: conforme texto da cláusula}','Todo dia 1 do mês','Pagamento liquidado + comprovante arquivado',NULL,22);
INSERT INTO "obligations" VALUES(2,1,'Contrato','5.6.2','Periódica - Conforme Vigência','Durante a Fase II, observar integralmente as condições previstas no PGI aprovado pela ARTESP na administração do Complexo Aeroportuário durante a Fase II.',NULL,'pending','Concessionária',NULL,3,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 19:06:50','OBR-0002','Fase II','Calendário (cron - vigência)','no_ciclo','Recorrência conforme texto contratual (Adicionado por IA: cadência identificada pela Recorrência)','Estudos de demanda e diagnóstico operacional','Manifestação ou aprovação da ARTESP; Tribunais e instâncias judiciais (quando aplicável)','—','—','recorrente','{frequência: conforme vigência; data_referência: conforme texto da cláusula}','Conforme vigência indicada na cláusula','Cumprimento evidenciado em auditoria',NULL,23);
INSERT INTO "obligations" VALUES(3,1,'Contrato','5.9. e 5.9.1.1','Pontual','No início da concessão, Estágio 1 da Fase I-A, após a adjudicação, iniciar intercâmbio com o DAESP para implantar nova organização e cultura nos aeroportos, elaborar um Plano de Transferência Operacional (PTO) para cada aeroporto e enviá-los à ARTESP em até 40 dias após a Data de Eficácia. Caso a ARTESP solicite complementação de informações do PTO, realizar a complementação no prazo de até 15 dias do recebimento da requisição. 5.9.1.1',NULL,'completed','Concessionária',NULL,4,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0003','Fase I-A (Estágio 1)','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Diagnóstico operacional dos aeroportos','Dados e coordenação com DAESP (operador anterior); Tribunais e instâncias judiciais (quando aplicável)','—','—','relativo_a_evento','{N: 40 dias; direção: após; evento: evento descrito na cláusula}','Em até 40 dias','Documento elaborado e arquivado',NULL,23);
INSERT INTO "obligations" VALUES(4,1,'Contrato','5.13','Pontual','No Estágio 2 (Operação Assistida), estabelecer uma equipe de transição com responsáveis pelas principais áreas funcionais, acompanhando diretamente a operação ainda sob responsabilidade do DAESP.',NULL,'completed','Concessionária',NULL,5,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0004','Fase I-A (Estágio 2)','Marco temporal (estágio/fase da concessão)','antes_do_ato','Marco de fase ou estágio da concessão','Cadastro e plano de capacitação de equipe','Dados e coordenação com DAESP (operador anterior); Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: variável; marco: Estágio 2 da Fase I-A}','Durante o Estágio 2 da Fase I-A','Cumprimento evidenciado conforme cláusula',NULL,24);
INSERT INTO "obligations" VALUES(5,1,'Contrato','5.14 / 5.14.1','Pontual','Durante o Estágio 2 da Fase I-A, trabalhar em conjunto com o Comitê de Transição e pessoas por ele indicadas para coordenar de forma transparente o início das atividades. Se o Comitê não estiver composto, atuar em conjunto com todos os agentes indicados pela ARTESP durante o Estágio 2.',NULL,'completed','Concessionária',NULL,6,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0005','Fase I-A (Estágio 2)','Marco temporal (estágio/fase da concessão)','antes_do_ato','Marco de fase ou estágio da concessão','—','—','—','—','offset_de_marco','{N: variável; marco: Estágio 2 da Fase I-A}','Durante o Estágio 2 da Fase I-A','Cumprimento evidenciado conforme cláusula',NULL,24);
INSERT INTO "obligations" VALUES(6,1,'Contrato','5.15','Pontual','Durante o Estágio 2, realizar um amplo processo de auditoria para familiarizar-se totalmente com as operações, estrutura organizacional, contratos de cessão de espaços e usuários.',NULL,'completed','Concessionária',NULL,7,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0006','Fase I-A (Estágio 2)','Marco temporal (estágio/fase da concessão)','antes_do_ato','Marco de fase ou estágio da concessão','—','—','—','—','offset_de_marco','{N: variável; marco: Estágio 2 da Fase I-A}','Durante o Estágio 2 da Fase I-A','Auditoria/vistoria realizada e documentada',NULL,24);
INSERT INTO "obligations" VALUES(7,1,'Contrato','5.16','Pontual','Durante a transição (Fase I-A), garantir uma transição eficaz, dentro dos prazos estabelecidos, executando as ações previstas no Anexo 04 e no PTO aprovado.',NULL,'completed','Concessionária',NULL,8,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0007','Fase I-A','Marco temporal (após Data de Eficácia)','antes_do_ato','Marco vinculado à entrega de plano que habilita fase seguinte','Diagnóstico operacional dos aeroportos','—','—','—','offset_de_marco','{N: até 18 meses; direção: após; marco: Data de Eficácia (Fase I-A)}','Durante a Fase I-A','Cumprimento evidenciado conforme cláusula',NULL,25);
INSERT INTO "obligations" VALUES(8,1,'Contrato','5.19','Pontual','Ao final do Estágio 2, na transferência dos contratos, comunicar todas as pessoas físicas e jurídicas envolvidas nos contratos do DAESP sobre a sub-rogação integral desses contratos pela concessionária, podendo revisar suas condições e adequá-los ao regime privado (inclusive extingui-los antecipadamente), sem direito a reequilíbrio caso as negociações não alcancem as condições almejadas.',NULL,'completed','Concessionária',NULL,9,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0008','Fase I-A (Estágio 2)','Marco temporal (estágio/fase da concessão)','antes_do_ato','Marco de fase ou estágio da concessão','—','Dados e coordenação com DAESP (operador anterior); Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: 0; direção: ao final; marco: estágio 2}','Ao final estágio 2','Cumprimento evidenciado conforme cláusula',NULL,25);
INSERT INTO "obligations" VALUES(9,1,'Contrato','5.19.4','Pontual','Durante a vigência dos contratos sub-rogados, manter o Estado de São Paulo e a ARTESP indenes de qualquer custo, responsabilidade ou pleito relacionado aos contratos sub-rogados do DAESP, devendo a concessionária mantê-los livres de litígios, em conformidade com a Cláusula 16.1, inciso (xxxvii).',NULL,'pending','Concessionária',NULL,10,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:00:30','OBR-0009','Todas as fases a partir da sub-rogação','Marco temporal (a confirmar)','antes_do_ato','Marco específico identificado na consulta ao contrato','—','Dados e coordenação com DAESP (operador anterior)','—','—','offset_de_marco','{N: variável; marco: vigência dos contratos sub-rogados}','Durante a vigência dos contratos sub-rogados','Estado mantido (auditável a qualquer momento)',NULL,25);
INSERT INTO "obligations" VALUES(10,1,'Contrato','5.20','Contínua','Não se sub-rogar em contratos do DAESP que envolvam exclusivamente prestação de serviços ao próprio DAESP (contratos que não geram exploração econômica de espaços aeroportuários permanecem sob responsabilidade do Estado). Condição inicial da concessão, devendo ser mantida durante toda concessão.',NULL,'pending','Concessionária',NULL,11,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0010','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Dados e coordenação com DAESP (operador anterior); Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,26);
INSERT INTO "obligations" VALUES(11,1,'Contrato','10.3','Contínua','Dar publicidade aos valores das tarifas aeroportuárias, divulgando-os nos aeroportos e em seu sítio eletrônico.',NULL,'pending','Concessionária',NULL,12,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0011','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Cálculos de reajuste tarifário','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,32);
INSERT INTO "obligations" VALUES(12,1,'Contrato','11.6 (i)','Contínua','Na exploração de receitas não tarifárias, realizar as atividades com qualidade e eficiência, exigindo o mesmo dos contratados, visando à conveniência para a prestação do serviço adequado, sem comprometer a segurança e qualidade dos serviços delegados.',NULL,'pending','Concessionária',NULL,13,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0012','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Receita auferida no período (tarifária e/ou não-tarifária); Cálculos de reajuste tarifário','Tribunais e instâncias judiciais (quando aplicável)','cl. 33.6 conta centralizadora','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,33);
