INSERT INTO "obligations" VALUES(36,1,'Contrato','15.1','Contínua','Observar a atualidade tecnológica na execução das obras e serviços da concessão, caracterizada pela preservação da modernidade e atualização dos equipamentos e instalações e, quando aplicável, das técnicas operacionais, desde que a atualização tecnológica seja necessária diante da obsolescência de bens ou para cumprimento dos indicadores de qualidade e demais exigências do contrato.',NULL,'pending','Concessionária',NULL,37,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0036','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Cumprimento evidenciado em auditoria',NULL,46);
