INSERT INTO "obligations" VALUES(38,1,'Contrato','15.3','Contínua','Levar em consideração a vida útil dos bens da concessão e o seu adequado aproveitamento e funcionamento; quando necessário, proceder à sua substituição por outros bens e equipamentos que apresentem tecnologia e condições de operação iguais ou superiores às dos substituídos, independentemente de determinação do Poder Concedente ou da ARTESP.',NULL,'pending','Concessionária',NULL,39,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0038','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Manifestação ou aprovação da ARTESP; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,46);
INSERT INTO "obligations" VALUES(39,1,'Contrato','15.5.1','Eventual (Sob Condição)','Se caracterizada a obsolescência tecnológica dos bens da concessão (perda relevante de função ou incapacidade de atender às exigências de qualidade), propor prazo para atendimento das exigências, considerando as vidas úteis e prazos de substituição, devendo, em qualquer hipótese, a substituição ocorrer, no máximo, até o termo final do contrato.',NULL,'pending','Concessionária',NULL,40,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0039','Todas as fases','Evento operacional interno','após_o_ato','Identificação interna de fim de vida útil ou inoperância de bem','Boletim interno de ocorrência','—','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Ação executada conforme cláusula + evidência arquivada',NULL,47);
INSERT INTO "obligations" VALUES(40,1,'Contrato','15.6','Contínua','Levar em consideração a atualidade dos serviços prestados na gestão operacional das atividades, inclusive relativas à gestão de recursos humanos e comunicação com usuários, clientes, fornecedores ou interessados.',NULL,'pending','Concessionária',NULL,41,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0040','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Fornecedores e prestadores de serviço; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,47);
INSERT INTO "obligations" VALUES(41,1,'Contrato','15.13','Contínua','O disposto na Cláusula 15 não afasta a obrigação da concessionária de adotar, implementar e custear toda e qualquer medida procedimental e/ou operacional, inclusive aquelas de natureza tributária, trabalhista e ambiental determinadas por órgãos fiscalizadores diversos da ARTESP, que não sejam específicas à concessão, sem direito a indenização ou reequilíbrio, desde que tais determinações não representem riscos atribuídos à ARTESP ou ao Poder Concedente.',NULL,'pending','Concessionária',NULL,42,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0041','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Laudos e avaliações ambientais internas; Documentação societária da SPE; Comprovantes de regularidade fiscal e tributária','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estrutura/regramento instituído e em vigor',NULL,48);
INSERT INTO "obligations" VALUES(42,1,'Contrato','16.1 (i)','Contínua','Prestar serviço adequado, cumprindo e fazendo cumprir integralmente o contrato, com zelo e diligência, utilizando a melhor técnica aplicável a cada tarefa, em conformidade com as disposições legais e regulamentares e as determinações da ARTESP, assumindo integral responsabilidade pelos riscos da execução da concessão (ressalvadas as hipóteses expressamente excepcionadas no contrato).',NULL,'pending','Concessionária',NULL,43,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0042','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Cumprimento evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(43,1,'Contrato','16.1 (ii)','Contínua','Prestar os serviços delegados sem interrupção, durante todo o período da concessão, de forma adequada ao pleno atendimento dos usuários, mantendo sempre em perfeita ordem todas as dependências vinculadas à execução do contrato, valendo-se de todos os meios e recursos para sua execução, em obediência às normas pertinentes, aos padrões e procedimentos deste contrato e àqueles determinados pela ARTESP, nos termos do art. 6º da Lei 8.987/1995, art. 17 da Lei 7.835/1992 e Lei 13.460/2017.',NULL,'pending','Concessionária',NULL,44,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0043','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(44,1,'Contrato','16.1 (iii)','Contínua','Cooperar e apoiar o desenvolvimento das atividades de acompanhamento e fiscalização da ARTESP, nos termos dos anexos deste contrato.',NULL,'pending','Concessionária',NULL,45,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0044','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Comprovantes de regularidade fiscal e tributária','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(45,1,'Contrato','16.1 (iv)','Contínua','Realizar, por meios próprios ou mediante terceiros, os investimentos obrigatórios e os investimentos previstos especificados neste contrato, no PEA e no PGI, responsabilizando-se integralmente por eles e impedindo que qualquer responsabilização recaia sobre o Poder Concedente ou sobre a ARTESP, especialmente no que se refere a questões trabalhistas e criminais, mesmo nos casos em que as obras e investimentos não sejam executados diretamente pela concessionária, observados os requisitos de tempestividade e qualidade estabelecidos.',NULL,'pending','Concessionária',NULL,46,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0045','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Estudos de demanda e diagnóstico operacional; Documentação societária da SPE','Fornecedores e prestadores de serviço; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(46,1,'Contrato','16.1 (v)','Contínua','Não celebrar contrato com terceiros cuja execução seja incompatível com o prazo da concessão, ressalvadas as situações expressamente previstas neste contrato.',NULL,'pending','Concessionária',NULL,47,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0046','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Fornecedores e prestadores de serviço','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(47,1,'Contrato','16.1 (vi)','Eventual (Sob Condição)','Refazer, adequar ou corrigir, direta ou indiretamente, sem qualquer ônus ao Poder Concedente, à ARTESP ou à execução dos serviços delegados, toda e qualquer obra ou serviço realizado de maneira indevida ou em desconformidade com os padrões de qualidade estabelecidos neste contrato, observando os prazos definidos pela ARTESP.',NULL,'pending','Concessionária',NULL,48,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0047','Todas as fases','Evento condicional (sob hipótese específica)','após_o_ato','Ocorrência da hipótese descrita na cláusula','Registros contábeis da SPE; Saldo da Conta Centralizadora','—','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Ação executada conforme cláusula + evidência arquivada',NULL,48);
