INSERT INTO "obligations" VALUES(49,1,'Contrato','16.1 (viii)','Eventual (Sob Condição)','Apresentar, após as revisões ordinárias e extraordinárias do contrato, cronogramas físico-financeiro e físico-executivo, juntamente com o PGI, que contenham o planejamento da execução dos investimentos, com marcos, etapas, atividades e prazos que vincularão a concessionária, conforme o regramento deste contrato.',NULL,'pending','Concessionária',NULL,50,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0049','Todas as fases','Evento condicional (sob hipótese específica)','após_o_ato','Ocorrência da hipótese descrita na cláusula','Estudos de demanda e diagnóstico operacional','—','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Ação executada conforme cláusula + evidência arquivada',NULL,48);
INSERT INTO "obligations" VALUES(50,1,'Contrato','16.1 (ix)','Eventual (Sob Condição)','Quando necessário, após revisões contratuais, elaborar e submeter à ARTESP eventual revisão do Plano de Seguros e/ou do Plano de Garantias que seja necessária, inclusive em razão das revisões ordinárias e extraordinárias, os quais deverão detalhar as condições dos seguros e garantias a serem contratados e observar o cronograma de investimentos previsto, de modo que assegurem os riscos envolvidos em sua execução.',NULL,'pending','Concessionária',NULL,51,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0050','Todas as fases','Evento condicional (sob hipótese específica)','após_o_ato','Ocorrência da hipótese descrita na cláusula','Apólices de seguro e garantias contratuais','—','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Cumprimento evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(51,1,'Contrato','16.1 (x)','Contínua','Manter vigente a Garantia de Execução e os seguros necessários, nos termos dispostos neste contrato.',NULL,'pending','Concessionária',NULL,52,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0051','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Apólices de seguro e garantias contratuais','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,48);
INSERT INTO "obligations" VALUES(52,1,'Contrato','16.1 (xi)','Contínua','Manter, durante a vigência da concessão, todas as condições de habilitação e qualificação exigidas na licitação que forem necessárias à continuidade da execução dos investimentos obrigatórios, dos investimentos previstos e dos serviços delegados.',NULL,'pending','Concessionária',NULL,53,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0052','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,48);
INSERT INTO "obligations" VALUES(53,1,'Contrato','16.1 (xii)','Contínua','Elaborar todos os estudos, projetos e demais documentos necessários ao cumprimento do objeto deste contrato, inclusive corrigindo projetos quando necessário, observados os prazos definidos pela ARTESP e de acordo com as disposições deste contrato, do PEA e demais anexos.',NULL,'pending','Concessionária',NULL,54,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0053','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Documento elaborado e arquivado',NULL,48);
INSERT INTO "obligations" VALUES(54,1,'Contrato','16.1 (xiii)','Contínua','Prestar informações e esclarecimentos requisitados pelo Poder Concedente, pela ARTESP ou pela ANAC, garantindo-lhes acesso amplo, irrestrito e a qualquer tempo a todas as dependências do Complexo Aeroportuário, de modo a franquear a fiscalização e a realização de auditorias necessárias.',NULL,'pending','Concessionária',NULL,55,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0054','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Comprovantes de regularidade fiscal e tributária','Coordenação ou aprovação da ANAC; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(55,1,'Contrato','16.1 (xiv)','Periódica - Anual','Apresentar anualmente relatório contendo as informações da concessão, nos termos deste contrato e da regulamentação vigente e nos prazos definidos, incluindo, em especial, todas as informações previstas no Anexo 02 e no Anexo 04 (dados de tráfego de aeronaves, passageiros e cargas, valores arrecadados com tarifas) e as memórias de cálculo de valores devidos à ARTESP ou ao Estado de São Paulo.',NULL,'pending','Concessionária',NULL,56,1,'sofiaishizaki.2@gmail.com',NULL,NULL,'yearly','08:00',NULL,NULL,NULL,NULL,'2027-06-09 08:00:00.000000','2027-05-10 08:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0055','Todas as fases','Calendário (cron anual)','no_ciclo','anualmente (data específica não identificada no texto) (Adicionado por IA: cadência anual identificada pela Recorrência)','Dados operacionais consolidados do período; Documentação societária da SPE; Cálculos de reajuste tarifário','Tribunais e instâncias judiciais (quando aplicável)','—','—','recorrente','{frequência: anual; data_referência: conforme texto da cláusula}','Anual','Relatório apresentado e protocolado na ARTESP',NULL,48);
INSERT INTO "obligations" VALUES(56,1,'Contrato','16.1 (xv)','Contínua','Dispor de banco de dados atualizado, em base eletrônica, apto a gerar relatório contendo as informações da concessão, nos termos deste contrato e da regulamentação vigente e nos prazos definidos, em especial todas as informações previstas no Anexo 02 e no Anexo 04 (dados estatísticos de tráfego de aeronaves, passageiros e cargas, valores arrecadados com tarifas), assegurando ao Poder Concedente, à ARTESP e à ANAC o acesso ininterrupto, irrestrito e imediato a esse banco de dados.',NULL,'pending','Concessionária',NULL,57,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0056','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Dados operacionais consolidados do período; Diagnóstico operacional dos aeroportos; Documentação societária da SPE; Cálculos de reajuste tarifário','Coordenação ou aprovação da ANAC; Financiadores / instituições financeiras; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(57,1,'Contrato','16.1 (xvi)','Contínua','Manter a ARTESP e a ANAC informadas sobre toda e qualquer ocorrência em desconformidade com a operação adequada do Complexo Aeroportuário, assim considerada o não atendimento ao estabelecido no PEA ou eventual descumprimento de norma legal ou regulamentar do setor.',NULL,'pending','Concessionária',NULL,58,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0057','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Boletim interno de ocorrência','Coordenação ou aprovação da ANAC; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,48);
INSERT INTO "obligations" VALUES(58,1,'Contrato','16.1 (xvii)','Eventual (Sob Condição)','Comunicar imediatamente à ARTESP e adotar as providências necessárias sempre que ocorrer a descoberta de materiais ou objetos de interesse geológico ou arqueológico, bem como superveniências de caráter ambiental ou de interferências.',NULL,'pending','Concessionária',NULL,59,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0058','Todas as fases','Evento operacional crítico','após_o_ato','Ocorrência ou acidente que demande resposta imediata','Laudos e avaliações ambientais internas','—','—','cl. 16.1 (xiv) relatório anual geral (consolidação)','relativo_a_evento','{N: imediato; direção: após; evento: ocorrência descrita na cláusula}','Imediato','Comunicação formal arquivada',NULL,48);
