INSERT INTO "obligations" VALUES(73,1,'Contrato','16.1 (xxxii)','Contínua','Responder, por si ou por seus administradores, empregados, prepostos, subcontratados, prestadores de serviços ou qualquer outra pessoa física ou jurídica relacionada à execução do objeto do contrato, perante o Poder Concedente, a ARTESP e terceiros, por todos e quaisquer danos causados por atos comissivos ou omissivos da concessionária, sempre que decorrerem da execução das obras e prestação dos serviços sob sua responsabilidade, direta ou indireta, não excluindo ou reduzindo tal responsabilidade a fiscalização ou o acompanhamento do contrato pela ARTESP.',NULL,'pending','Concessionária',NULL,74,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0073','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Comprovantes de regularidade fiscal e tributária','Fornecedores e prestadores de serviço; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(74,1,'Contrato','16.1 (xxxiii)','Contínua','Prever a responsabilização de seus agentes por danos que causarem a terceiros, aos usuários e, quando for o caso, ao Poder Público, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.',NULL,'pending','Concessionária',NULL,75,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0074','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Fornecedores e prestadores de serviço; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(75,1,'Contrato','16.1 (xxxiv)','Eventual (Sob Condição)','Dar conhecimento à ARTESP, à ANAC e ao Estado de São Paulo de todo e qualquer evento que altere de modo relevante o normal desenvolvimento da prestação dos serviços delegados, ou que possa vir a prejudicar ou impedir o pontual e tempestivo cumprimento das obrigações previstas no contrato, incluindo-se ações judiciais ou procedimentos administrativos; apresentar, por escrito e no prazo máximo de 3 dias contados da data em que constatados, relatório detalhado sobre esses fatos, inclusive dos termos e prazos processuais, bem como envidar os melhores esforços na defesa dos interesses comuns, praticando todos os atos processuais cabíveis.',NULL,'pending','Concessionária',NULL,76,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,'cl. 16.1 (xix) reporte em 24h; cl. 14.1 operação adequada',NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:00:30','OBR-0075','Todas as fases','Evento operacional/jurídico de alto impacto','após_o_ato','Evento relevante que altere o normal desenvolvimento dos serviços','Dados operacionais consolidados do período','Coordenação ou aprovação da ANAC; Tribunais e instâncias judiciais (quando aplicável)','cl. 16.1 (xix) reporte em 24h; cl. 14.1 operação adequada','—','relativo_a_evento','{N: 3 dias; direção: após; evento: constatação do fato}','No prazo de 3 dias após constatação do fato','Relatório apresentado e protocolado na ARTESP',NULL,48);
