INSERT INTO "obligations" VALUES(77,1,'Contrato','16.1 (xxxvi)','Contínua','Responsabilizar-se pela assinatura e atendimento de compromissos assumidos em Termos de Ajustamento de Conduta (TAC) ou instrumentos congêneres, firmados com órgãos competentes, a partir da Data de Eficácia, no que diz respeito aos atos comissivos ou omissivos da concessionária na execução do objeto deste contrato.',NULL,'pending','Concessionária',NULL,78,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0077','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Documentação societária da SPE','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
INSERT INTO "obligations" VALUES(78,1,'Contrato','16.1 (xxxvii)','Contínua','Ressarcir ou indenizar e manter o Estado de São Paulo e a ARTESP indenes em relação a qualquer demanda ou prejuízo que venham a sofrer em virtude, dentre outros: (a) de desembolsos decorrentes de determinações judiciais ou arbitrais de qualquer espécie, mesmo acrescidos de juros e encargos legais, para satisfação de obrigações originalmente imputáveis à concessionária, inclusive reclamações trabalhistas propostas por empregados ou terceiros vinculados à concessionária, bem como a danos a usuários, terceiros e órgãos de controle e fiscalização; (b) de ato praticado pela concessionária no âmbito da execução do contrato, bem como por seus administradores, empregados, prepostos, prestadores de serviços, terceiros com quem tenha contratado, inclusive o subcontratado, ou qualquer outra pessoa a ela vinculada; (c) de questões de natureza fiscal, trabalhista, previdenciária ou acidentária relacionadas aos empregados da concessionária e de terceiros contratados; (d) de danos ambientais causados pela concessionária na implantação e na execução dos serviços delegados e das atividades geradoras de receitas alternativas, complementares, acessórias e de projetos associados; (e) de despesas processuais, honorários de advogado e demais encargos com os quais venha a arcar em função das ocorrências descritas nas alíneas anteriores.','A responsabilidade da concessionária prevista neste inciso perdurará mesmo depois de encerrado o contrato, podendo a ARTESP e o Estado buscar o ressarcimento junto aos acionistas da concessionária, na forma da legislação societária, no caso de extinção da pessoa jurídica.','pending','Concessionária',NULL,79,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0078','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Receita auferida no período (tarifária e/ou não-tarifária); Boletim interno de ocorrência; Laudos e avaliações ambientais internas; Documentação societária da SPE; Comprovantes de regularidade fiscal e tributária','Fornecedores e prestadores de serviço; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,48);
INSERT INTO "obligations" VALUES(79,1,'Contrato','16.1 (xxxviii)','Contínua','Apoiar a ARTESP e outros órgãos e entidades públicas na execução de serviços que estejam fora do objeto da concessão, mas se relacionem com ele, conforme detalhado no Anexo 02.',NULL,'pending','Concessionária',NULL,80,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0079','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,48);
