INSERT INTO "obligations" VALUES(129,1,'Contrato','50.1','Encerramento da Concessão','Com 3 anos de antecedência ao termo contratual, ou imediatamente no caso de extinção antecipada do contrato, submeter à aprovação da ARTESP o Plano de Desmobilização do Complexo Aeroportuário, que deverá prever o procedimento pelo qual será realizada a desmobilização e reversão dos bens reversíveis, sem que ocorra qualquer interrupção na prestação dos serviços, observando o procedimento previsto no Anexo 16.',NULL,'pending','Concessionária','2049-03-31 00:00:00.000000',130,1,'sofiaishizaki.2@gmail.com',NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,'2048-10-02 00:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0129','Encerramento','Marco temporal (fim da concessão)','antes_do_ato','Aproximação do término final da concessão','Inventário atualizado de bens reversíveis','Manifestação ou aprovação da ARTESP; Tribunais e instâncias judiciais (quando aplicável)','—','—','relativo_a_evento','{N: imediato; direção: após; evento: ocorrência descrita na cláusula}','3 anos antes do término: 31/03/2049','Cumprimento evidenciado conforme cláusula',NULL,129);
INSERT INTO "obligations" VALUES(130,1,'Contrato','50.4','Encerramento da Concessão','Quando faltar 1 ano para o término do contrato, a concessionária deverá treinar o pessoal indicado pela ARTESP, bem como repassar a documentação técnica, administrativa e as orientações operacionais relativas ao complexo que ainda não tiverem sido entregues, observado o disposto na Cláusula 49.',NULL,'pending','Concessionária','2051-03-31 00:00:00.000000',131,1,'sofiaishizaki.2@gmail.com',NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,'2050-10-02 00:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0130','Encerramento','Marco temporal (fim da concessão)','antes_do_ato','Aproximação do término final da concessão','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: variável; direção: antes; marco: término da concessão}','1 ano antes do término: 31/03/2051','Cumprimento evidenciado conforme cláusula',NULL,130);
