INSERT INTO "obligations" VALUES(159,1,'Anexo 1 - Regulamento da Concessão','Artigo 12, caput','Eventual (Sob Condição)','Ao reajustar ou estabelecer tarifas, observar as diretrizes do contrato de concessão e as isenções tarifárias previstas em leis e normas vigentes (por exemplo, Resolução ANAC nº 392/2016 e Portaria COMAER nº 219/GC-5/2001).',NULL,'pending','Concessionária',NULL,160,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0159','Todas as fases','Evento condicional (sob hipótese específica)','após_o_ato','Ocorrência da hipótese descrita na cláusula','Cálculos de reajuste tarifário','Coordenação ou aprovação da ANAC; Coordenação com COMAER/DECEA','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Cumprimento evidenciado em auditoria',NULL,14);
INSERT INTO "obligations" VALUES(160,1,'Anexo 1 - Regulamento da Concessão','Artigo 14','Contínua','Estimular a participação da comunidade em assuntos de interesse dos aeroportos abrangidos pela concessão, em conjunto com a ARTESP.',NULL,'pending','Concessionária',NULL,161,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0160','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,15);
INSERT INTO "obligations" VALUES(161,1,'Anexo 1 - Regulamento da Concessão','Artigo 15','Eventual (Sob Condição)','Promover as desapropriações e instituir servidões administrativas necessárias à eventual ampliação dos aeroportos, bem como arcar com as indenizações correspondentes, após declaração de utilidade pública das áreas pelo Poder Concedente (mediante proposta da concessionária), conforme as condições do contrato.',NULL,'pending','Concessionária',NULL,162,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0161','Todas as fases','Decisão administrativa precedente','antes_do_ato','Determinação de desapropriação pelo Estado ou anuência da ARTESP para obras','Minuta de decreto, plantas, laudos e documentação para DUP','Estado de São Paulo (declaração de utilidade pública); Tribunais e instâncias judiciais (quando aplicável)','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Estrutura/regramento instituído e em vigor',NULL,16);
INSERT INTO "obligations" VALUES(162,1,'Anexo 1 - Regulamento da Concessão','Artigo 16','Encerramento da Concessão','Devolver ao Poder Concedente, ao término da concessão, todos os bens reversíveis, direitos e privilégios vinculados à exploração dos aeroportos, incluindo os bens transferidos à concessionária ou por ela implantados, conforme previsto em lei e no contrato.',NULL,'pending','Concessionária','2052-03-31 00:00:00.000000',163,1,'sofiaishizaki.2@gmail.com',NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,'2051-10-03 00:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0162','Encerramento','Marco temporal (fim da concessão)','antes_do_ato','Aproximação do término final da concessão','Inventário atualizado de bens reversíveis','Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: variável; direção: antes; marco: término da concessão}','Término da concessão: 31/03/2052','Cumprimento evidenciado conforme cláusula',NULL,16);
INSERT INTO "obligations" VALUES(163,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.1.1','Contínua','Prestar serviços aeroportuários de embarque, desembarque, pouso, permanência, armazenagem e capatazia, bem como demais serviços de infraestrutura aeroportuária (exceto serviços de navegação aérea).',NULL,'pending','Concessionária',NULL,164,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0163','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,7);
INSERT INTO "obligations" VALUES(164,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.1.2','Contínua','Explorar eficientemente os complexos aeroportuários para obter receitas não tarifárias, disponibilizando aos usuários infraestrutura de apoio necessária ao bom funcionamento dos aeroportos.',NULL,'pending','Concessionária',NULL,165,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0164','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Receita auferida no período (tarifária e/ou não-tarifária); Cálculos de reajuste tarifário','—','cl. 33.6 conta centralizadora','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,7);
INSERT INTO "obligations" VALUES(165,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.1.3','Contínua','Manter todas as instalações, bens e equipamentos existentes e implementados nos aeroportos em adequado estado de conservação e funcionamento, conforme a legislação e regulamentação em vigor.',NULL,'pending','Concessionária',NULL,166,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0165','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,8);
INSERT INTO "obligations" VALUES(166,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.1.4','Pontual','Executar as melhorias de infraestrutura previstas no PEA dentro dos prazos estabelecidos, visando ampliar e adequar a infraestrutura aeroportuária e elevar a qualidade dos serviços prestados aos usuários.','Refere-se aos investimentos iniciais e demais melhorias obrigatórias descritas no PEA e apêndices, com prazos definidos (especialmente os investimentos da Fase I-B e da Fase II). O não cumprimento nos prazos pode acarretar penalidades contratuais.','pending','Concessionária',NULL,167,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 19:06:50','OBR-0166','Fase I-B / Fase II','Marco temporal (estágio/fase da concessão)','antes_do_ato','Marco de fase ou estágio da concessão','Documentação societária da SPE','—','—','—','offset_de_marco','{N: até 48 meses; direção: após; marco: Data de Eficácia (Fase I-B)}','Durante a Fase I-B (até 48 meses)','Cumprimento evidenciado conforme cláusula',NULL,8);
INSERT INTO "obligations" VALUES(167,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.1.5','Contínua','Garantir o pleno atendimento ao nível de serviço previsto no PEA durante toda a Fase II da concessão, mediante realização dos investimentos e ações operacionais necessários e obtenção dos recursos requeridos.',NULL,'pending','Concessionária',NULL,168,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 19:06:50','OBR-0167','Fase II','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,8);
INSERT INTO "obligations" VALUES(168,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.1.6','Contínua','Assegurar o balanceamento entre as diversas instalações aeroportuárias (terminais, pátios, pistas, estacionamentos, acessos etc.), de forma que a infraestrutura mantenha capacidade adequada para atender usuários durante toda a concessão.',NULL,'pending','Concessionária',NULL,169,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0168','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Boletim interno de ocorrência','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,8);
INSERT INTO "obligations" VALUES(169,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.2.6','Contínua','Operar e manter os auxílios visuais à navegação aérea (PAPI, VASIS, ALS, balizamentos de pista e táxi, farol de aeródromo, biruta etc.), que são de responsabilidade da Concessionária.','Embora os serviços de navegação aérea (ATM, AIS, MET, COM, SAR) sejam excluídos da concessão (atribuição do DECEA), a concessionária deve garantir funcionamento dos auxílios visuais de apoio à navegação e aterrissagem nos aeroportos.','pending','Concessionária',NULL,170,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0169','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','Coordenação com COMAER/DECEA; Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,8);
INSERT INTO "obligations" VALUES(170,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.3','Eventual (Sob Condição)','Arcar com os custos de eventual realocação de instalações e equipamentos relacionados aos serviços excluídos (itens 3.2.1 a 3.2.6 do Anexo II) caso a realocação seja motivada por obra ou serviço proposto pela concessionária.','Se a concessionária realizar obras que exijam deslocar equipamentos de navegação aérea do DECEA, deverá custear a realocação e providenciar infraestrutura equivalente para que tais equipamentos continuem operando.','pending','Concessionária',NULL,171,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'eventual',NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0170','Todas as fases','Evento condicional (sob hipótese específica)','após_o_ato','Ocorrência da hipótese descrita na cláusula','—','Coordenação com COMAER/DECEA; Tribunais e instâncias judiciais (quando aplicável)','—','—','relativo_a_evento','{N: não definido no texto; direção: após; evento: ocorrência da condição}','Não explicitado numericamente na cláusula','Ação executada conforme cláusula + evidência arquivada',NULL,8);
INSERT INTO "obligations" VALUES(171,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3.4 e 3.5.','Eventual (Sob Condição)','A Concessionária poderá prestar serviços de navegação aérea (hoje a cargo do DECEA), por sua conta e risco, mediante anuência prévia do COMAER, incluindo realizar investimentos relacionados a esses serviços.','Esta cláusula permite, mas não obriga, a concessionária a assumir serviços como torre de controle, meteorologia etc. Caso o faça, não terá direito a reequilíbrio econômico-financeiro por esses investimentos.
INSERT INTO "obligations" VALUES(172,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','4.1.3 e 4.1.3.1','Eventual (Sob Condição)','Não utilizar as “áreas especiais” do COMAER.
INSERT INTO "obligations" VALUES(173,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','4.1.5 e 4.1.5.1','Eventual (Sob Condição)','Se quiser expandir os complexos aeroportuários além das áreas contempladas no Apêndice E, a concessionária deverá tomar todas as medidas administrativas e judiciais necessárias para regularizar a posse e a exploração dessas novas áreas.
INSERT INTO "obligations" VALUES(174,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','5.1. à 5.9','Contínua','Atender as especificações dos itens 5.1 a 5.9, que tratam das especificações mínimas dos Terminais de Passageiros.',NULL,'pending','Concessionária',NULL,175,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0174','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Documentação societária da SPE','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,12);
INSERT INTO "obligations" VALUES(175,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','5.10','Contínua','Caberá à concessionária evidenciar, por meio de documentos (próprios ou de terceiros), que atendeu às especificações dos itens 5.1 a 5.9, que tratam das especificações mínimas dos Terminais de Passageiros.',NULL,'pending','Concessionária',NULL,176,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0175','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Documentação societária da SPE','Fornecedores e prestadores de serviço','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,13);
INSERT INTO "obligations" VALUES(176,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','5.10.1','Periódica - Anual','A obrigação prevista no item 5.10 (comprovação dos itens 5.1–5.9) deverá constar do Relatório Anual de Monitoramento do PGI, conforme previsto no PEA e no Contrato.',NULL,'pending','Concessionária',NULL,177,1,'sofiaishizaki.2@gmail.com',NULL,NULL,'yearly','08:00',NULL,NULL,NULL,NULL,'2027-06-09 08:00:00.000000','2027-05-10 08:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0176','Todas as fases','Calendário (cron anual)','no_ciclo','cadência anual (Adicionado por IA: cadência anual identificada pela Recorrência)','Dados operacionais consolidados do período; Estudos de demanda e diagnóstico operacional','Tribunais e instâncias judiciais (quando aplicável)','—','—','recorrente','{frequência: anual; data_referência: conforme texto da cláusula}','Anual','Cumprimento evidenciado conforme cláusula',NULL,13);
INSERT INTO "obligations" VALUES(177,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','6.1','Contínua','Todos os investimentos na infraestrutura devem ser realizados de modo a atender os Parâmetros Mínimos de Dimensionamento, os Indicadores de Qualidade de Serviços e demais regras do Contrato e Anexos, garantindo que os aeroportos estejam plenamente operacionais ao final da concessão.',NULL,'pending','Concessionária',NULL,178,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0177','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','—','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,14);
INSERT INTO "obligations" VALUES(178,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','6.2','Pontual','A concessionária deverá executar todos os INVESTIMENTOS OBRIGATÓRIOS indicados pelas normas vigentes para que cada aeroporto possa receber a aeronave crítica inicial prevista (Apêndice G), até o final da Fase I-B do Contrato (48 meses a partir da efetivação).
INSERT INTO "obligations" VALUES(179,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','6.2.2 e 6.2.3','Contínua','Também considerados INVESTIMENTOS OBRIGATÓRIOS aqueles necessários à manutenção de padrões operacionais mínimos: banheiros e fraldários em condições de uso, ausência de infiltrações, pintura sem manchas/desgastes, e sinalização e iluminação mínimas nas vias de acesso, estacionamento e áreas de fluxo de passageiros, principalmente se houver voos noturnos.',NULL,'pending','Concessionária',NULL,180,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0179','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Cronograma de manutenção preventiva e corretiva','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Compliance contínuo evidenciado em auditoria',NULL,14);
