INSERT INTO "obligations" VALUES(218,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','7.1','Pontual','A concessionária deverá elaborar e entregar o PGI de cada aeroporto à ARTESP no Estágio 3 da Fase I-A, em prazo não superior a 180 dias da Data de Eficácia do contrato.',NULL,'completed','Concessionária',NULL,219,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:00:30','OBR-0218','Fase I-A (Estágio 3)','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Estudos de demanda e diagnóstico operacional','—','cl. 1.1 do Anexo 4 (PTO); cl. 5.13 a 5.16 operação assistida','cl. 6.x do Anexo 2 (cronograma de investimentos); cl. 7.5.1 (objeto de revisões antecipadas)','offset_de_marco','{N: 180 dias; direção: após; marco: Data de Eficácia}','180 dias após a Data de Eficácia','Plano entregue e protocolado na ARTESP',NULL,43);
INSERT INTO "obligations" VALUES(219,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','7.5','Pontual','A cada 5 anos a partir da Data de Eficácia, serão conduzidos os processos de Revisão Ordinária da concessão, os quais poderão culminar em revisão do PGI, do PEA ou elaboração de novos planos, bem como de seus cronogramas, Plano de Seguros, Plano de Garantias e Indicadores de Qualidade de Serviço.',NULL,'pending','Concessionária',NULL,220,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:00:30','OBR-0219','Fase II','Marco temporal (após Data de Eficácia)','antes_do_ato','Marco vinculado à entrega de plano que habilita fase seguinte','Estudos de demanda e diagnóstico operacional; Apólices de seguro e garantias contratuais','Tribunais e instâncias judiciais (quando aplicável)','—','—','recorrente','{frequência: a cada 5 anos; data_referência: a partir da Data de Eficácia}','A cada 5 anos a partir da Data de Eficácia','Cumprimento evidenciado conforme cláusula',NULL,44);
INSERT INTO "obligations" VALUES(220,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','7.5.1 a 7.5.1.3.','Eventual (Sob Condição)','A Concessionária deverá apresentar uma revisão antecipada do PGI caso ocorra qualquer das seguintes hipóteses antes da próxima Revisão Ordinária: (i) a demanda real de hora pico superar ou cair mais de 20% em relação à demanda prevista no PGI para aquele ano; (ii) o aeroporto pretenda iniciar operação de voos regulares (de passageiros) antes da próxima revisão, ou voos regulares assumidos no PGI não se concretizarem; ou (iii) o aeroporto pretenda receber aeronaves de categoria superior à prevista até então, antes da próxima revisão ordinária.
INSERT INTO "obligations" VALUES(221,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','7.7','Pontual','Ao elaborar o PGI de um aeroporto, a concessionária deverá demonstrar que deu conhecimento do PGI às Empresas Aéreas que operam voos regulares nesse aeroporto (não é exigida consulta a empresas que não operaram voos regulares nos últimos 12 meses).',NULL,'completed','Concessionária',NULL,222,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0221','Fase I-A (Estágio 3)','Marco temporal (após Data de Eficácia)','antes_do_ato','Marco vinculado à entrega de plano que habilita fase seguinte','Estudos de demanda e diagnóstico operacional','—','cl. 1.1 do Anexo 4 (PTO); cl. 5.13 a 5.16 operação assistida','—','offset_de_marco','{N: durante elaboração; marco: elaboração do PGI}','Durante elaboração do PGI (Estágio 3 da Fase I-A)','Documento elaborado e arquivado',NULL,45);
INSERT INTO "obligations" VALUES(222,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','7.14','Periódica - Anual','A Concessionária deverá preparar o Relatório Anual de Monitoramento do PGI e entregá-lo à ARTESP nos termos das Cláusulas 36.6.1 e 36.6.1.1 do Contrato.',NULL,'pending','Concessionária',NULL,223,1,'sofiaishizaki.2@gmail.com',NULL,NULL,'yearly','08:00',NULL,NULL,NULL,NULL,'2027-06-09 08:00:00.000000','2027-05-10 08:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0222','Todas as fases','Calendário (cron anual)','no_ciclo','cadência anual (Adicionado por IA: cadência anual identificada pela Recorrência)','Dados operacionais consolidados do período; Estudos de demanda e diagnóstico operacional','—','—','—','recorrente','{frequência: anual; data_referência: conforme texto da cláusula}','Anual','Cumprimento evidenciado conforme cláusula',NULL,47);
INSERT INTO "obligations" VALUES(223,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','7.16','Contínua','Caso o planejamento da concessionária (contido no PGI) implique descumprimento de qualquer obrigação contratual, a concessionária estará sujeita a penalidades conforme o Contrato e Anexo 17, e deverá implementar as medidas necessárias para atender ao nível de serviço e manter a infraestrutura adequada, sem direito a reequilíbrio econômico-financeiro.','*','pending','Concessionária',NULL,224,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0223','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Estudos de demanda e diagnóstico operacional','Tribunais e instâncias judiciais (quando aplicável)','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,47);
INSERT INTO "obligations" VALUES(224,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','3. do Apêndice B','Periódica - Anual','A Concessionária deverá encaminhar, até o dia 1º do mês de aniversário da concessão de cada ano, relatório contendo as informações relativas ao nível de serviço alcançado no horário de pico, para cada um dos componentes previstos no Apêndice B, acompanhado da respectiva memória de cálculo.',NULL,'pending','Concessionária',NULL,225,1,'sofiaishizaki.2@gmail.com',NULL,NULL,'yearly','08:00',NULL,NULL,NULL,NULL,'2027-04-01 00:00:00.000000','2027-03-02 00:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0224','Todas as fases','Calendário (cron anual)','no_ciclo','mês de aniversário da Data de Eficácia (Adicionado por IA: cadência anual identificada pela Recorrência)','Dados operacionais consolidados do período; Documentação societária da SPE','—','—','—','recorrente','{frequência: anual; data_referência: mês de aniversário da Data de Eficácia}','Todo 1º de abril','Cumprimento evidenciado conforme cláusula',NULL,NULL);
INSERT INTO "obligations" VALUES(225,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','4. do Apêndice C.','Periódica - Mensal','Encaminhamento periódico à ARTESP das informações coletadas pelo sistema de registro, incluindo análise crítica dos principais problemas, plano de ação para mitigação ou correção, registro das ações realizadas, avaliação de sua efetividade e indicação do sistema utilizado para identificar, documentar e rastrear as necessidades dos usuários, ficando o sistema sujeito à auditoria da ARTESP a qualquer tempo.','Aplicável apenas para Aeroportos com movimentação anual de passageiros igual
