INSERT INTO "obligations" VALUES(228,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','26. e 35 do Apêndice C','Pontual','Encaminhar o primeiro Plano de Qualidade de Serviço (PQS) até o mês de aniversário da Concessão anterior a cada reajuste. A Concessionária devera encaminhar juntamente com o PQS, os protocolos de concordancia, referentes aos Acordos de Nivel de Serviço entre a Concessionária e Empresas Aéreas atuantes no Aeroporto.','*','completed','Concessionária',NULL,229,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0228','Fase I-A (mês de aniversário da concessão)','Marco temporal (após Data de Eficácia)','antes_do_ato','Marco vinculado à entrega de plano que habilita fase seguinte','Indicadores de qualidade de serviço; Cálculos de reajuste tarifário','—','cl. 7.1 do Anexo 2 (PGI)','—','recorrente','{frequência: anual; data_referência: mês de aniversário da Concessão anterior a cada reajuste}','Mês de aniversário da Concessão anterior a cada reajuste','Cumprimento evidenciado conforme cláusula',NULL,NULL);
