INSERT INTO "obligations" VALUES(230,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','4. do Apêndice D.','Periódica - Mensal','Encaminhar periodicamente a ARTESP as informações coletadas por meio do sistema de registro.','Aplicável apenas para Aeroportos com movimentagao anual inferior a 1 milhão de passageiro ao ano.','pending','Concessionária',NULL,231,1,'sofiaishizaki.2@gmail.com',NULL,NULL,'monthly','08:00',NULL,NULL,NULL,NULL,'2026-07-01 00:00:00.000000','2026-06-24 00:00:00.000000',NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:41:19','OBR-0230','Todas as fases','Calendário (cron mensal)','no_ciclo','Fechamento de mês (Adicionado por IA: cadência mensal explicitada pela Recorrência)','—','Cartórios e órgãos de registro','—','—','recorrente','{frequência: mensal; data_referência: conforme texto da cláusula}','Todo dia 1 do mês','Cumprimento evidenciado conforme cláusula',NULL,NULL);
