INSERT INTO "obligations" VALUES(232,1,'Anexo 2 - Plano de Exploração Aeroportuária (PEA)','1.1.2 do Apêndice F','Pontual','Efetivado o reenquadramento do aeroporto em Faixa superior, realizar as adequações necessárias ao pleno atendimento dos requisitos contratuais exigidos para esta Faixa, no prazo de prazo de 22 (vinte e dois) meses, a contar do dia 1° do mês subsequente ao da efetivação do reenquadramento.',NULL,'pending','Concessionária',NULL,233,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:00:30','OBR-0232','Fase I-B / Fase II','Marco temporal (a confirmar)','antes_do_ato','Marco específico identificado na consulta ao contrato','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','relativo_a_evento','{N: 22 meses; direção: após; evento: efetivação do reenquadramento}','22 meses após efetivação do reenquadramento','Cumprimento evidenciado conforme cláusula',NULL,123);
INSERT INTO "obligations" VALUES(233,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','1.1','Pontual','Desenvolver um Plano de Transferência Operacional (PTO) para cada aeroporto do bloco da concessão e enviá-lo à ARTESP em até 40 dias após a Data de Eficácia.',NULL,'completed','Concessionária',NULL,234,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 22:00:30','OBR-0233','Fase I-A (Estágio 1)','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Diagnóstico operacional dos aeroportos','—','—','cl. 7.1 do Anexo 2 (PGI); cl. 5.13 a 5.16 operação assistida','relativo_a_evento','{N: 40 dias; direção: após; evento: evento descrito na cláusula}','Em até 40 dias','Documento elaborado e arquivado',NULL,3);
INSERT INTO "obligations" VALUES(234,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','1.4','Pontual','Demonstrar à ARTESP, durante os Estágios 1 e 2 da Fase 1-A, a capacidade de compreender e analisar a operação aeroportuária.',NULL,'completed','Concessionária',NULL,235,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0234','Fase I-A','Marco temporal (a confirmar)','antes_do_ato','Marco específico identificado na consulta ao contrato','Boletim interno de ocorrência','Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: até 18 meses; direção: após; marco: Data de Eficácia (Fase I-A)}','Durante a Fase I-A','Demonstração formal protocolada',NULL,3);
INSERT INTO "obligations" VALUES(235,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','2.1 e 2.2.','Pontual','Criar e liderar o Comitê de Transição, com participação de representantes do DAESP, da ARTESP, do órgão de controle de tráfego aéreo (quando aplicável), da própria concessionária (administração do aeroporto) e de outros órgãos ou entidades relevantes. O Comitê de Transição se reunirá em até 30 dias após a Data de Eficácia e deverá permanecer ativo ate o término da Fase l-A.',NULL,'completed','Concessionária',NULL,236,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0235','Fase I-A','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Documentação societária da SPE','Dados e coordenação com DAESP (operador anterior); Tribunais e instâncias judiciais (quando aplicável)','—','—','relativo_a_evento','{N: 30 dias; direção: após; evento: evento descrito na cláusula}','Em até 30 dias','Cumprimento evidenciado conforme cláusula',NULL,3);
INSERT INTO "obligations" VALUES(236,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','2.3','Pontual','Assegurar que o Comitê de Transição se reúna mensalmente ou sempre que convocado pela ARTESP. Os protocolos para as reuniões do Comitê de Transição estão disciplinados nos itens 2.4. a 2.5.','A ARTESP pode convocar reuniões extraordinárias para acompanhar e dar suporte ao processo de transição operacional. As reuniões mensais são obrigatórias durante a fase de transição, garantindo monitoramento contínuo do PTO.','completed','Concessionária',NULL,237,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0236','Fase I-A','Marco temporal (após Data de Eficácia)','antes_do_ato','Marco vinculado à entrega de plano que habilita fase seguinte','Diagnóstico operacional dos aeroportos','—','—','—','offset_de_marco','{N: até 18 meses; direção: após; marco: Data de Eficácia (Fase I-A)}','Durante a Fase I-A','Cumprimento evidenciado conforme cláusula',NULL,3);
INSERT INTO "obligations" VALUES(237,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','3.5','Pontual','A CONCESSIONARIA devera estabelecer uma equipe de transição para assumir as responsabilidades da operação do Aeroporto durante o periodo de transição. Como parte da Equipe de Transição, apresentar, em até 10 dias da Data de Eficácia, uma Equipe de Gestão do aeroporto, composta pelo gestor do aeroporto e pelos responsáveis por segurança operacional, operações aeroportuárias, manutenção e resposta à emergência, conforme previsto no RBAC 153.',NULL,'completed','Concessionária',NULL,238,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0237','Fase I-A','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Cronograma de manutenção preventiva e corretiva; Cadastro e plano de capacitação de equipe','Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: 10 dias; direção: após; marco: Data de Eficácia}','Em até 10 dias após a Data de Eficácia','Cumprimento evidenciado conforme cláusula',NULL,4);
