INSERT INTO "obligations" VALUES(250,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','4.4.3.1 a 4.4.3.3','Pontual','Elaborar um documento informativo sobre a nova organização do aeroporto, descrevendo a estrutura proposta e os papéis correspondentes, agendar visitas da nova equipe de gestão para fornecer informações aos funcionários atuais sobre a nova organização e apresentar os novos gestores e propor reuniões informativas com os atuais concessionários de áreas (locatários comerciais, etc.) e outros interessados, a fim de fornecer informações e apresentar os novos gestores.',NULL,'completed','Concessionária',NULL,251,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 19:10:28.504315','OBR-0250','Fase I-A (Estágio 1 ou 2)','Marco temporal (a confirmar)','antes_do_ato','Marco específico identificado na consulta ao contrato','Cadastro e plano de capacitação de equipe','Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: variável; marco: Estágio 1 ou 2 da Fase I-A}','Durante a transição (Estágio 1 ou 2)','Documento elaborado e arquivado',NULL,7);
