INSERT INTO "obligations" VALUES(252,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','4.4.5','Contínua','Para aeroportos com menos de 50.000 passageiros/ano (ou sem voos regulares), manter apenas as condições mínimas de manutenção já existentes, desde que estejam aceitáveis para a função a que se destinam.',NULL,'pending','Concessionária',NULL,253,1,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0252','Todas as fases','Estado permanente (sem disparo)','durante_o_estado','Vigência do contrato — estado a ser mantido continuamente','Cronograma de manutenção preventiva e corretiva','—','—','—','não_aplicável','—','Estado permanente — durante toda a vigência','Estado mantido (auditável a qualquer momento)',NULL,7);
INSERT INTO "obligations" VALUES(253,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','4.4.6','Pontual','Reportar à ARTESP, em até 180 dias após a Data de Eficácia, as ações de melhoria previstas nos itens 4.4.4 e 4.4.5. O relatório deve informar as intervenções a serem realizadas, locais, período de execução, responsáveis, e incluir registro fotográfico das áreas que sofrerão intervenção (se for o caso).',NULL,'completed','Concessionária',NULL,254,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 21:58:07','OBR-0253','Fase I-A (Estágio 3)','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Dados operacionais consolidados do período','Cartórios e órgãos de registro','—','cl. 16.1 (xiv) relatório anual geral (consolidação)','relativo_a_evento','{N: 180 dias; direção: após; evento: evento descrito na cláusula}','Em até 180 dias','Reporte escrito entregue à ARTESP (e demais destinatários previstos)',NULL,8);
