INSERT INTO "obligations" VALUES(256,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','4.4.13','Pontual','Coordenar, juntamente com o Comitê de Transição, a execução de um plano de relações públicas durante a transição. Este plano deve construir um relacionamento positivo com todos os stakeholders-chave, iniciando um diálogo contínuo e participação desses interessados na melhoria contínua do aeroporto.',NULL,'completed','Concessionária',NULL,257,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0256','Fase I-A','Marco temporal (a confirmar)','antes_do_ato','Marco específico identificado na consulta ao contrato','—','Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: até 18 meses; direção: após; marco: Data de Eficácia (Fase I-A)}','Durante a Fase I-A','Cumprimento evidenciado conforme cláusula',NULL,8);
INSERT INTO "obligations" VALUES(257,1,'Anexo 4 - Plano de Transferência Operacional (PTO)','5.1.1','Pontual','Logo após a assinatura/adjudicação do contrato, iniciar o intercâmbio com o DAESP (atual operador) para implantar uma nova organização e cultura nos aeroportos. Para tanto, elaborar planos e programas específicos de transição, que em conjunto constituem o PTO, a ser encaminhado à ARTESP em até 40 dias da Data de Eficácia.',NULL,'completed','Concessionária',NULL,258,0,NULL,NULL,NULL,NULL,'08:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'pendente','2026-06-09 20:58:51','2026-06-10 18:21:41.188933','OBR-0257','Fase I-A','Marco temporal (após Data de Eficácia)','antes_do_ato','Data de Eficácia + N dias/meses','Diagnóstico operacional dos aeroportos; Documentação societária da SPE','Dados e coordenação com DAESP (operador anterior); Tribunais e instâncias judiciais (quando aplicável)','—','—','offset_de_marco','{N: 40 dias; direção: após; marco: Data de Eficácia}','Em até 40 dias após a Data de Eficácia','Documento elaborado e arquivado',NULL,9);
