INSERT INTO "obligations" VALUES(274,1,'Contrato','37.5 (i–x)','Eventual (Sob Condição)','Comunicar à ARTESP, em até 15 dias após consumados, os seguintes atos e operações praticados pela concessionária (sob pena de sanções contratuais): (i) alterações na composição acionária da SPE que não impliquem transferência de controle, mas que impliquem transferência de, no mínimo, 20% das ações com direito a voto; (ii) alterações na composição acionária da SPE que não impliquem transferência de controle, mas que impliquem transferência de, no mínimo, 10% das ações com direito a voto da SPE detidas por um único acionista; (iii) alterações nos acordos de voto aplicáveis a eventual bloco de controle, desde que não impliquem transferência de controle; (iv) perda de qualquer condição essencial, pela SPE, à prestação dos serviços delegados; (v) alteração do Estatuto Social da SPE, de natureza eminentemente formal e/ou procedimental; (vi) aplicação de penalidades à SPE, por qualquer órgão ou entidade competente, especialmente quanto à inadimplência de obrigações tributárias, previdenciárias, de segurança e medicina do trabalho, ou aplicadas por órgãos reguladores/fiscalizadores, ou de caráter ambiental; (vii) ajuizamento, por terceiros, de pedido de recuperação judicial ou de qualquer outro processo concursal ou de liquidação da SPE; (viii) substituição do responsável técnico da SPE; (ix) subcontratação ou terceirização de serviços relativos à exploração de receitas não tarifárias; (x) contratação de financiamento, emissão de títulos e valores mobiliários, ou qualquer outra operação de dívida, contratação de seguros e garantias, que não se enquadrem na hipótese da Cláusula 37.1 (viii).',NULL,'pending','Concessionária',NULL,NULL,1,'sofiaishizaki.2@gmail.com',NULL,'2026-06-10 15:33:14.216370','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-06-10 15:33:14.216370','enviado','eventual',NULL,'cl. 33.6 conta centralizadora',NULL,'pendente','2026-06-09 23:33:51','2026-06-11 17:20:54','OBR-0128','Todas as fases','Ato societário ou financeiro consumado','após_o_ato','Prática consumada de ato listado no contrato','Receita auferida no período (tarifária e/ou não-tarifária); Laudos e avaliações ambientais internas; Documentação societária da SPE; Documentação financeira e contratos de financiamento; Apólices de seguro e garantias contratuais; Cálculos de reajuste tarifário; Comprovantes de regularidade fiscal e tributária','Fornecedores e prestadores de serviço; Tribunais e instâncias judiciais (quando aplicável)','cl. 33.6 conta centralizadora','cl. 16.1 (xiv) relatório anual geral (consolidação)','relativo_a_evento','{N: 15 dias; direção: após; evento: evento descrito na cláusula}','Em até 15 dias','Comunicação formal arquivada',NULL,109);
